#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <unistd.h>

#define N 5
#define LEFT (id + N - 1) % N
#define RIGHT (id + 1) % N

enum { THINKING, HUNGRY, EATING } state[N];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* philosopher(void* arg) {
    int id = *(int*)arg;
    for (int i = 0; i < 1000; i++) {
        pthread_mutex_lock(&lock);
        state[id] = HUNGRY;
        if (state[LEFT] == EATING || state[RIGHT] == EATING) {
            pthread_cond_wait(&cond, &lock);
        }
        assert(state[LEFT] != EATING && state[RIGHT] != EATING);
        state[id] = EATING;
        pthread_mutex_unlock(&lock);

        pthread_mutex_lock(&lock);
        state[id] = THINKING;
        pthread_cond_broadcast(&cond);
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

int main(void) {
    pthread_t t[N];
    int ids[N];
    for (int i = 0; i < N; i++) {
        ids[i] = i;
        pthread_create(&t[i], NULL, philosopher, &ids[i]);
    }
    for (int i = 0; i < N; i++) pthread_join(t[i], NULL);
    return 0;
}

#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <unistd.h>

#define THREADS 4
#define WORK_ITEMS 10000

int ready_work = 0;
int active = 1;
int total_sum = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* worker(void* arg) {
    while (active) {
        pthread_mutex_lock(&lock);
        if (ready_work == 0 && active) {
            pthread_cond_wait(&cond, &lock);
        }
        if (!active) { pthread_mutex_unlock(&lock); break; }
        assert(ready_work > 0);
        ready_work--;
        total_sum += 10;
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

int main(void) {
    pthread_t threads[THREADS];
    for (int i = 0; i < THREADS; i++) pthread_create(&threads[i], NULL, worker, NULL);
    for (int i = 0; i < WORK_ITEMS; i++) {
        pthread_mutex_lock(&lock);
        ready_work = 1;
        pthread_cond_broadcast(&cond);
        pthread_mutex_unlock(&lock);
        usleep(10);
    }
    pthread_mutex_lock(&lock);
    active = 0;
    pthread_cond_broadcast(&cond);
    pthread_mutex_unlock(&lock);
    for (int i = 0; i < THREADS; i++) pthread_join(threads[i], NULL);
    return 0;
}

