#define THREADS 4

int balance = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* withdrawer(void* arg) {
    for (int i = 0; i < 500; i++) {
        pthread_mutex_lock(&lock);
        if (balance < 10) {
            pthread_cond_wait(&cond, &lock);
        }
        assert(balance >= 10);
        balance -= 10;
        pthread_mutex_unlock(&lock);
        usleep(100);
    }
    return NULL;
}

void* depositor(void* arg) {
    for (int i = 0; i < 1000; i++) {
        pthread_mutex_lock(&lock);
        balance += 10;
        pthread_cond_broadcast(&cond);
        pthread_mutex_unlock(&lock);
        usleep(100);
    }
    return NULL;
}

int main(void) {
    pthread_t w[THREADS], d;
    pthread_create(&d, NULL, depositor, NULL);
    for (int i = 0; i < THREADS; i++) pthread_create(&w[i], NULL, withdrawer, NULL);
    pthread_join(d, NULL);
    for (int i = 0; i < THREADS; i++) pthread_join(w[i], NULL);
