#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <unistd.h>

#define CONSUMERS 4
#define CAPACITY 10

int log_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* log_consumer(void* arg) {
    for (int i = 0; i < 1000; i++) {
        pthread_mutex_lock(&lock);
        if (log_count == 0) {
            pthread_cond_wait(&cond, &lock);
        }
        assert(log_count > 0);
        log_count--;
        pthread_mutex_unlock(&lock);
        usleep(50);
    }
    return NULL;
}

void* log_producer(void* arg) {
    for (int i = 0; i < 2000; i++) {
        pthread_mutex_lock(&lock);
        if (log_count < CAPACITY) {
            log_count++;
            pthread_cond_broadcast(&cond);
        }
        pthread_mutex_unlock(&lock);
        usleep(50);
    }
    return NULL;
}

int main(void) {
    pthread_t prod, cons[CONSUMERS];
    pthread_create(&prod, NULL, log_producer, NULL);
    for (int i = 0; i < CONSUMERS; i++) pthread_create(&cons[i], NULL, log_consumer, NULL);
    pthread_join(prod, NULL);
    for (int i = 0; i < CONSUMERS; i++) pthread_join(cons[i], NULL);
    return 0;
}

