#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

int fork_busy[2] = {0, 0};

void *philosopher(void *arg) {
    int id = *(int *)arg;
    int left = id;
    int right = (id + 1) % 2;
    for (int i = 0; i < 5; i++) {
        while (fork_busy[left]) {
            usleep(100);
        }
        fork_busy[left] = 1;
        for(int j=0; j<50000; j++);

        while (fork_busy[right]) {
            usleep(100);
