#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>

#define NUM_READERS 5
#define NUM_WRITERS 2

int hit_counter = 0;
int read_count = 0;

sem_t mutex;
sem_t db;

void *reader(void *arg) {
    (void)arg;
    for (int i = 0; i < 10; i++) {
        sem_wait(&mutex);
        read_count++;
        if (read_count == 1) {
            sem_wait(&db);
        }
        sem_post(&mutex);

        volatile int val = hit_counter;
        (void)val;

        sem_wait(&mutex);
        read_count--;
        if (read_count == 0) {
            sem_post(&db);
        }
        sem_post(&mutex);
    }
    return NULL;
}

void *writer(void *arg) {
    (void)arg;
    for (int i = 0; i < 5; i++) {
        sem_wait(&db);
        hit_counter++;
        sem_post(&db);
    }
    return NULL;
}

int main(void) {
    pthread_t readers[NUM_READERS];
    pthread_t writers[NUM_WRITERS];

    sem_init(&mutex, 0, 1);
    sem_init(&db, 0, 1);

    for (int i = 0; i < NUM_READERS; i++) {
        pthread_create(&readers[i], NULL, reader, NULL);
    }
    for (int i = 0; i < NUM_WRITERS; i++) {
        pthread_create(&writers[i], NULL, writer, NULL);
    }

    for (int i = 0; i < NUM_READERS; i++) {
        pthread_join(readers[i], NULL);
    }
    for (int i = 0; i < NUM_WRITERS; i++) {
        pthread_join(writers[i], NULL);
    }

    printf("Final hit counter: %d\n", hit_counter);

    sem_destroy(&mutex);
    sem_destroy(&db);
    return 0;
}

