sem_t empty, full, mutex;

void init_sems() {
    sem_init(&empty, 0, N);
    sem_init(&full, 0, 0);
    sem_init(&mutex, 0, 1);
}

void* car(void* arg) {
    int id = *(int*)arg;
    for (int i = 0; i < 100000; i++) {
        sem_wait(&mutex);
        sem_wait(&full);
        int spot = -1;
        for (int j = 0; j < N; j++) {
            if (parking_lot[j] == 0) {
                spot = j;
                break;
            }
        }
        if (spot == -1) {
            printf("Car %d: no spot available\n", id);
            continue;
        }
        parking_lot[spot] = 1;
        sem_post(&empty);
        sem_post(&mutex);
        usleep(1000);
    }
    return NULL;
}

int main() {
    pthread_t cars[N * 2];
    int ids[N * 2];
    init_sems();

    for (int i = 0; i < N * 2; i++) {
        ids[i] = i;
        pthread_create(&cars[i], NULL, car, &ids[i]);
    }

    for (int i = 0; i < N * 2; i++) {
        pthread_join(cars[i], NULL);
    }

    return 0;
}

